<template><div><h1>Login</h1><AppInput v-model="email" placeholder="Email"/><AppInput v-model="password" type="password" placeholder="Password"/><AppButton @click="submit">Login</AppButton><router-link to="/register">Register</router-link></div></template>
<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../stores/auth';import AppInput from '../components/AppInput.vue';import AppButton from '../components/AppButton.vue';const email=ref('demo@smartpantry.app');const password=ref('demo1234');const auth=useAuthStore();const router=useRouter();const submit=async()=>{await auth.login({email:email.value,password:password.value});router.push('/');};</script>
